preamble:
COPY <<'RESILIENCY' /dapr/airlock/resiliency.yaml
apiVersion: dapr.io/v1alpha1
kind: Resiliency
metadata:
  name: airlock
spec:
  policies:
    circuitBreakers:
      sink:
        maxRequests: 1
        interval: 60s
        timeout: 30s
        trip: consecutiveFailures >= 10
  targets:
    apps:
      illustrate-card: {circuitBreaker: sink}
      smollm3-draft: {circuitBreaker: sink}
      heavy-draft: {circuitBreaker: sink}
      print-quote: {circuitBreaker: sink}
      print-quote-br: {circuitBreaker: sink}
      print-fx: {circuitBreaker: sink}
      print-session: {circuitBreaker: sink}
      print-check: {circuitBreaker: sink}
      print-place: {circuitBreaker: sink}
      print-place-br: {circuitBreaker: sink}
      print-status: {circuitBreaker: sink}
      print-status-br: {circuitBreaker: sink}
      print-confirm: {circuitBreaker: sink}
      print-record: {circuitBreaker: sink}
      print-shipped: {circuitBreaker: sink}
      print-alert: {circuitBreaker: sink}
RESILIENCY
